package com.fitnutri.backend.records.workout;
import com.fitnutri.backend.common.BusinessException;
import com.fitnutri.backend.profile.ProfileService;
import com.fitnutri.backend.records.*;
import com.fitnutri.backend.support.*;
import com.fitnutri.backend.user.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.fitnutri.backend.records.workout.ExerciseEntryInputs.*;
@SpringBootTest @ActiveProfiles("integration-test")
class ExerciseEntryReadIT{
 static final TestDatabase DB=TestDatabase.create();static{Runtime.getRuntime().addShutdownHook(new Thread(DB::close));}
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",DB::url);r.add("spring.datasource.username",DB::username);r.add("spring.datasource.password",DB::password);}
 @Autowired ExerciseEntryReadService reads;@Autowired ExerciseRecentService recent;@Autowired WorkoutEstimateService previews;@Autowired ExerciseEntryV2Service creates;@Autowired WorkoutMutationService mutations;@Autowired UserRepository users;@Autowired ProfileService profiles;@Autowired JdbcTemplate jdbc;
 User owner;WorkoutV2TestFixtures.Catalogue catalogue;LocalDate day=LocalDate.of(2020,1,2);long workout,quick,legacy;
 @BeforeEach void setup(){owner=FoodV2TestFixtures.owner(users,profiles);catalogue=WorkoutV2TestFixtures.catalogue(jdbc);workout=create(false);quick=create(true);legacy=jdbc.queryForObject("INSERT INTO exercise_record(user_id,created_at,recorded_at,recorded_date,client_entry_id,source,exercise_type,duration_minutes,intensity,estimated_calories) VALUES(?,now(),now(),?,gen_random_uuid(),'PHOTO','Retained legacy name',12.34,'HIGH',123.456) RETURNING id",Long.class,owner.getId(),day);}
 long create(boolean quick){return create(quick,null);}
 long create(boolean quick,String origin){var p=new PreviewPeriod(UUID.randomUUID(),"STRENGTH",Long.toString(catalogue.strengthOption()),new BigDecimal("50"),Map.of(),List.of(new Movement(catalogue.movements().getFirst().toString(),3L,null,new BigDecimal("40"))));var c=new PreviewPeriod(UUID.randomUUID(),"ACTIVITY",Long.toString(catalogue.cardioOption()),new BigDecimal("20"),Map.of(),List.of());PreviewEntry entry=quick?new QuickPreview(c.clientEntryId(),c):new WorkoutPreview(UUID.randomUUID(),"Synthetic read workout",List.of(p,c),origin);var preview=previews.previewNew(owner.getId(),new PreviewRequest(day,"Australia/Sydney",RecordSource.MANUAL,entry));var ps=entry instanceof QuickPreview q?List.of(q.period()):((WorkoutPreview)entry).periods();var confirmed=new ArrayList<Period>();for(int i=0;i<ps.size();i++){var row=ps.get(i);confirmed.add(new Period(row.clientEntryId(),row.periodKind(),row.optionId(),row.durationMinutes(),row.equipmentDetails(),row.movements(),preview.periods().get(i).calculationFingerprint()));}Entry input=quick?new Quick(entry.clientEntryId(),confirmed.getFirst()):new Workout(entry.clientEntryId(),"Synthetic read workout",confirmed,origin);return Long.parseLong(creates.createEntryV2(owner.getId(),new CreateRequest(UUID.randomUUID(),day,"Australia/Sydney",RecordSource.MANUAL,preview.fingerprint(),input)).roots().getFirst().id());}
 @Test void mixedRootPagingKeepsAllPeriodsTogetherAndNeverCountsMovements(){var all=reads.listRoots(owner.getId(),day,day,"Australia/Sydney",0,20);assertEquals(3,all.totalMatches());assertEquals(3,all.results().size());var detail=reads.getOwnedRoot(owner.getId(),"workout",workout);assertEquals(new BigDecimal("70.00"),((WorkoutEstimateService.Response)detail.preview()).totalMinutes());assertEquals(new BigDecimal("1342.366"),((WorkoutEstimateService.Response)detail.preview()).knownEnergyKj());assertEquals(2,detail.periodDetails().size());assertEquals(2,detail.periodCount());assertEquals(1,detail.periodDetails().getFirst().movements().size());Set<String> keys=new HashSet<>();for(int page=0;page<3;page++){var one=reads.listRoots(owner.getId(),day,day,"Australia/Sydney",page,1);assertEquals(1,one.results().size());var root=one.results().getFirst();keys.add(((Map<?,?>)root.input()).get("kind").toString().toLowerCase(java.util.Locale.ROOT)+":"+root.id());assertEquals(page<2,one.hasMore());}assertEquals(3,keys.size());}
 @Test void absentWorkoutOriginIsOmittedFromStrictReadContractButRealOriginIsRetained(){
  var original=reads.getOwnedRoot(owner.getId(),"workout",workout);
  assertFalse(((Map<?,?>)original.input()).containsKey("originWorkoutId"),"Optional non-null contract fields must be absent when no origin exists");
  long immutable=create(false);assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->jdbc.update("UPDATE workout_record SET origin_workout_id=? WHERE id=? AND user_id=?",workout,immutable,owner.getId()));
  assertFalse(((Map<?,?>)reads.getOwnedRoot(owner.getId(),"workout",immutable).input()).containsKey("originWorkoutId"));
  long reused=create(false,Long.toString(workout));var copy=reads.getOwnedRoot(owner.getId(),"workout",reused);
  assertEquals(Long.toString(workout),((Map<?,?>)copy.input()).get("originWorkoutId"));
  assertEquals(2,copy.periodCount());assertEquals(2,copy.periodDetails().size());
 }
 @Test void legacyReadPreservesUnknownsNameIntensityCaloriesAndQualityWithoutWrites(){var before=jdbc.queryForMap("SELECT * FROM exercise_record WHERE id=?",legacy);var root=reads.getOwnedRoot(owner.getId(),"quick",legacy);assertEquals(DataQuality.LEGACY_UNVERIFIED,root.dataQuality());assertEquals("Retained legacy name",root.displayName());assertEquals("IMAGE",root.source());var input=(Map<?,?>)root.input();var p=(Map<?,?>)input.get("period");assertNull(p.get("referenceId"));assertEquals("HIGH",p.get("legacyIntensity"));assertEquals(new BigDecimal("123.456"),new BigDecimal(p.get("legacyEstimatedCalories").toString()));assertNull(((Map<?,?>)root.preview()).get("knownEnergyKj"));assertEquals(before,jdbc.queryForMap("SELECT * FROM exercise_record WHERE id=?",legacy));}
 @Test void recentUsesCreatedAtAndReportsUnavailableOriginalWithoutChangingSnapshots(){jdbc.update("UPDATE exercise_option SET active=false WHERE id=?",catalogue.strengthOption());var detail=reads.getOwnedRoot(owner.getId(),"workout",workout);assertFalse(detail.periodDetails().getFirst().selectableForNew());assertEquals(Long.toString(catalogue.strengthOption()),detail.periodDetails().getFirst().option().id());assertEquals("STRENGTH",detail.periodDetails().getFirst().option().periodKind());assertEquals(List.of(),detail.periodDetails().getFirst().option().allowedDetails());var originalMovement=detail.periodDetails().getFirst().movements().getFirst();assertEquals(originalMovement.catalogueId(),originalMovement.catalogue().id());assertEquals(originalMovement.loadBasis(),originalMovement.catalogue().loadBasis());assertEquals(List.of("setCount","repetitions","loadKg"),originalMovement.catalogue().allowedFields());assertEquals("Synthetic movement 0",detail.periodDetails().getFirst().movements().getFirst().name());assertEquals("TOTAL_BARBELL",detail.periodDetails().getFirst().movements().getFirst().loadBasis());jdbc.update("UPDATE exercise_record SET recorded_date=DATE '2020-01-01' WHERE id=?",quick);var latest=recent.recentEntries(owner.getId(),5);assertEquals(2,latest.results().size());assertEquals(Long.toString(quick),latest.results().getFirst().id());assertEquals(0,latest.page());assertEquals(10,latest.size());}
 @Test void ownersDeletedChildrenAndRangesAreStrict(){var other=FoodV2TestFixtures.owner(users,profiles);assertEquals("NOT_FOUND",assertThrows(BusinessException.class,()->reads.getOwnedRoot(other.getId(),"workout",workout)).code());long child=jdbc.queryForObject("SELECT min(id) FROM exercise_record WHERE workout_id=?",Long.class,workout);assertEquals("NOT_FOUND",assertThrows(BusinessException.class,()->reads.getOwnedRoot(owner.getId(),"quick",child)).code());assertThrows(BusinessException.class,()->reads.listRoots(owner.getId(),day,day.plusDays(366),"Australia/Sydney",0,20));assertThrows(BusinessException.class,()->reads.listRoots(owner.getId(),day,day,"Australia/Sydney",-1,20));assertThrows(BusinessException.class,()->recent.recentEntries(owner.getId(),101));mutations.softDeleteOwnedRoot(owner.getId(),"workout",workout,0L);assertEquals(2,reads.listRoots(owner.getId(),day,day,"Australia/Sydney",0,20).totalMatches());assertEquals(1,recent.recentEntries(owner.getId(),5).results().size());}
}
